"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[39964],{94482:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Builds a hidden bar on `adornee`, owned by `cleaner`. Returns `hit(previous, health, max)`:\\ncall it on every health drop. `worldOffset` replaces the template offset (studs, world up).","params":[{"name":"adornee","desc":"","lua_type":"BasePart"},{"name":"cleaner","desc":"","lua_type":"Janitor.Janitor"},{"name":"worldOffset","desc":"","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"(number, number, number) -> ()\\n"}],"function_type":"static","source":{"line":45,"path":"src/ReplicatedStorage/SharedModules/NpcHealthBar.luau"}}],"properties":[],"types":[],"name":"NpcHealthBar","desc":"The enemy health bar: a clone of `ReplicatedStorage.GuiAssets.NpcHealthBar`\\n(BillboardGui, parented to PlayerGui). It shows on a health drop and hides\\n`EnemyBrainConfig.HealthBarHideAfter` s after the last one.\\n10 cells like the player HP bar: cell i fill = `clamp(h / max * 10 - (i - 1), 0, 1)`.\\n`Ghost` is the damage chip: it holds the old health, then eases down.\\nUsed by `NpcHitFxController` (pirate boarders) and `VoidEnemyController` (void enemies).\\n\\nTemplate names are load-bearing: `Frame/Cell1..10/{Ghost, Fill}`.","realm":["Client"],"source":{"line":15,"path":"src/ReplicatedStorage/SharedModules/NpcHealthBar.luau"}}')}}]);